+/**
+ * Return a single one-based page of `items` as a shallow copy.
+ *
+ * The caller's array is never mutated and never returned by reference: `items`
+ * is produced with `Array.prototype.slice`, so callers may freely mutate the
+ * result without affecting the input.
+ *
+ * A `page` beyond the last page yields an empty `items` array (the offset is
+ * simply past the end and `slice` clamps it). An empty input yields
+ * `pageCount: 0`.
+ *
+ * @template T
+ * @param {T[]} items source array, left untouched
+ * @param {number} page one-based page number
+ * @param {number} [pageSize=defaultPageSize] items per page
+ * @returns {{items: T[], total: number, pageCount: number}}
+ * @throws {RangeError} if `page` or `pageSize` is not a positive integer
+ */
+export function paginate(items, page, pageSize = defaultPageSize) {
+  if (!isPositiveInteger(page)) {
+    throw new RangeError(`page must be a positive integer, received: ${String(page)}`);
+  }
+  if (!isPositiveInteger(pageSize)) {
+    throw new RangeError(`pageSize must be a positive integer, received: ${String(pageSize)}`);
