+import test from 'node:test';
+import assert from 'node:assert/strict';
+import {csvCell} from '../src/csv.mjs';
+
+test('returns plain strings unchanged', () => {
+  assert.equal(csvCell('hello'), 'hello');
+  assert.equal(csvCell('Hello World'), 'Hello World');
+  assert.equal(csvCell('no special characters 123'), 'no special characters 123');
+});
+
+test('converts numbers to strings', () => {
+  assert.equal(csvCell(42), '42');
+  assert.equal(csvCell(0), '0');
+  assert.equal(csvCell(-7), '-7');
+  assert.equal(csvCell(3.5), '3.5');
+});
+
+test('returns empty strings unchanged and unquoted', () => {
+  assert.equal(csvCell(''), '');
+  assert.equal(csvCell(' '), ' ');
+});
+
+test('quotes cells containing a comma', () => {
+  assert.equal(csvCell('a,b'), '"a,b"');
+  assert.equal(csvCell('one,two,three'), '"one,two,three"');
+});
+
+test('quotes cells containing a newline', () => {
+  assert.equal(csvCell('a\nb'), '"a\nb"');
+  assert.equal(csvCell('\n'), '"\n"');
+});
+
+test('escapes double quotes by doubling them', () => {
+  assert.equal(csvCell('say "hi"'), '"say ""hi"""');
+  assert.equal(csvCell('"'), '""""');
+});
+
+test('quotes and escapes a cell combining comma, newline and double quotes', () => {
+  assert.equal(csvCell('a,"b"\nc'), '"a,""b""\nc"');
+});
